module.exports = "<div [ngClass]=\"getTableClasses()\">\n  @if (showSearch() || filtersVisible()) {\n    <header class=\"bmb_table-header\">\n      <div class=\"bmb_table-filter\">\n        @if (showSearch()) {\n          <section class=\"bmb_table-filter-item bmb_table-filter-item-search\">\n            <bmb-input\n              class=\"bmb_table-search\"\n              [type]=\"'text'\"\n              [placeholder]=\"'table.filters.search' | translate\"\n              [disabled]=\"false\"\n              [icon]=\"'search'\"\n              [appearance]=\"'normal'\"\n              [control]=\"searchControl\"\n            ></bmb-input>\n          </section>\n        }\n\n        @if (filtersVisible()) {\n          @for (column of parsedFiltersColumns(); track $index) {\n            <section class=\"bmb_table-filter-item\">\n              @switch (column.type) {\n                @case ('number') {\n                  <div class=\"bmb_table-filter-item-number\" margin=\"none\">\n                    <bmb-input\n                      [label]=\"column.label + ('table.filters.min' | translate)\"\n                      [type]=\"'number'\"\n                      [placeholder]=\"'Mín'\"\n                      [appearance]=\"'normal'\"\n                      [control]=\"getFormControl(column.dataKey + '_min')\"\n                    />\n                    <bmb-input\n                      [label]=\"column.label + ('table.filters.max' | translate)\"\n                      [type]=\"'number'\"\n                      [placeholder]=\"'Máx'\"\n                      [appearance]=\"'normal'\"\n                      [control]=\"getFormControl(column.dataKey + '_max')\"\n                    />\n                  </div>\n                }\n\n                @case ('date') {\n                  <bmb-date-range\n                    [placeholderStartDate]=\"'table.filters.startDatePlaceholder' | translate\"\n                    [placeholderEndDate]=\"'table.filters.endDatePlaceholder' | translate\"\n                    [icon]=\"'calendar_month'\"\n                    [labelEndDate]=\"'table.filters.endDate' | translate\"\n                    [labelStartDate]=\"'table.filters.startDate' | translate\"\n                    [dateFormat]=\"'dd/MM/yyyy'\"\n                    [controlStart]=\"getFormControl(column.dataKey + '_from')\"\n                    [controlEnd]=\"getFormControl(column.dataKey + '_to')\"\n                    (startDateChange)=\"\n                      getFormControl(column.dataKey + '_from').setValue($event)\n                    \"\n                    (endDateChange)=\"\n                      getFormControl(column.dataKey + '_to').setValue($event)\n                    \"\n                  />\n                }\n\n                @default {\n                  <bmb-input\n                    [label]=\"column.label\"\n                    [placeholder]=\"'table.filters.filter' | translate\"\n                    [control]=\"getFormControl(column.dataKey + '_contains')\"\n                  />\n                }\n              }\n            </section>\n          }\n        }\n      </div>\n    </header>\n  }\n  <div class=\"bmb_table-container\">\n    @if (showFilters()) {\n      <bmb-action-icon\n        [idElement]=\"''\"\n        [icon]=\"'filter_list'\"\n        [iconSize]=\"24\"\n        (buttonClick)=\"toggleFilters()\"\n      ></bmb-action-icon>\n    }\n    <section class=\"bmb_table-container-table\">\n      <table\n        mat-table\n        [dataSource]=\"dataSource\"\n        class=\"bmb_table-content\"\n        multiTemplateDataRows\n      >\n        <!-- Checkbox Column -->\n        <ng-container matColumnDef=\"select\" sticky>\n          <th mat-header-cell *matHeaderCellDef class=\"bmb_table-checkbox\">\n            <bmb-checkbox\n              (change)=\"handleMasterSelection($event)\"\n              [checked]=\"checkIfAllRowsSelected()\"\n              [indeterminate]=\"checkIfSomeRowsSelected()\"\n              [ariaLabel]=\"checkboxLabel()\"\n              [disabled]=\"false\"\n            />\n          </th>\n          <td mat-cell *matCellDef=\"let row\" class=\"bmb_table-checkbox\">\n            <bmb-checkbox\n              (change)=\"$event ? selection.toggle(row) : null; onSelect()\"\n              [checked]=\"selection.isSelected(row)\"\n              [ariaLabel]=\"checkboxLabel(row)\"\n              [disabled]=\"false\"\n              onkeypress=\"$event.stopPropagation()\"\n            />\n          </td>\n        </ng-container>\n\n        <!-- Expand Column -->\n        <ng-container matColumnDef=\"expand\" sticky>\n          <th\n            mat-header-cell\n            *matHeaderCellDef\n            class=\"bmb_table-expand\"\n            aria-label=\"row actions\"\n          >\n            &nbsp;\n          </th>\n          <td mat-cell *matCellDef=\"let row\" class=\"bmb_table-expand\">\n            <ng-container *ngIf=\"row.detail\">\n              <button\n                mat-icon-button\n                aria-label=\"expand row\"\n                (click)=\"\n                  expandedElement = expandedElement === row ? null : row;\n                  $event.stopPropagation()\n                \"\n              >\n                <bmb-icon\n                  [icon]=\"\n                    expandedElement === row ? 'zoom_out_map' : 'zoom_out_map'\n                  \"\n                />\n              </button>\n            </ng-container>\n          </td>\n        </ng-container>\n\n        <!-- Display Columns -->\n        @for (column of tableColumns; track column; let i = $index) {\n          <ng-container [matColumnDef]=\"column.def\" [sticky]=\"i === 0\">\n            <th\n              mat-header-cell\n              *matHeaderCellDef\n              #headerCell\n              [matTooltip]=\"hasEllipsis(headerCell) ? column.label : ''\"\n              matTooltipPosition=\"below\"\n              matTooltipClass=\"bmb_tooltip\"\n              [ngClass]=\"{\n                'bmb_table-sticky': i === 0,\n                truncated: truncate(),\n                wrapped: wrap()\n              }\"\n            >\n              <!-- Título -->\n              @if (column.htmlLabel) {\n                <ng-template\n                  [ngTemplateOutlet]=\"column.htmlLabel\"\n                  [ngTemplateOutletContext]=\"{ column: column, index: i }\"\n                ></ng-template>\n              } @else {\n                {{ this.lang() === 'es' ? column.label : column.labelEn }}\n              }\n\n              <!-- Resize Handle -->\n              <span\n                class=\"bmb_table-resize\"\n                (mousedown)=\"onResizeColumn($event, i)\"\n              ></span>\n            </th>\n\n            <td\n              mat-cell\n              *matCellDef=\"let row; let a = index\"\n              #cell\n              [matTooltip]=\"hasEllipsis(cell) ? row[column.dataKey] : ''\"\n              tooltipClass=\"bmb_tooltip\"\n              [ngClass]=\"getCellClasses(row, column.dataKey, i)\"\n            >\n              @if (isTemplateRef(row[column.dataKey + 'Template'])) {\n                <ng-template\n                  [ngTemplateOutlet]=\"row[column.dataKey + 'Template']\"\n                  [ngTemplateOutletContext]=\"{ row: row }\"\n                ></ng-template>\n              } @else {\n                {{ row[column.dataKey]?.propertyName || row[column.dataKey] }}\n              }\n            </td>\n          </ng-container>\n        }\n\n        <!-- Actions Column -->\n        <ng-container matColumnDef=\"actions\" stickyEnd>\n          <th mat-header-cell *matHeaderCellDef class=\"bmb_table-actions\"></th>\n          <td mat-cell *matCellDef=\"let row\" class=\"bmb_table-actions\">\n            <ng-template\n              [ngTemplateOutlet]=\"actionTemplate()!\"\n              [ngTemplateOutletContext]=\"{ row: row }\"\n            >\n            </ng-template>\n          </td>\n        </ng-container>\n\n        <!-- Row to expand -->\n        <ng-container matColumnDef=\"expandedDetail\">\n          <td\n            mat-cell\n            *matCellDef=\"let row\"\n            [attr.colspan]=\"tableDisplayColumns.length\"\n          >\n            <div\n              class=\"bmb_table-detail\"\n              [@detailExpand]=\"\n                row == expandedElement ? 'expanded' : 'collapsed'\n              \"\n            >\n              <ng-container\n                *ngTemplateOutlet=\"detailTemplate(); context: { row: row }\"\n              ></ng-container>\n            </div>\n          </td>\n        </ng-container>\n\n        <!-- Rows -->\n        <tr\n          mat-header-row\n          *matHeaderRowDef=\"tableDisplayColumns\"\n          class=\"bmb_table-row\"\n        ></tr>\n\n        <tr\n          mat-row\n          *matRowDef=\"let row; columns: tableDisplayColumns; let i = dataIndex\"\n          (click)=\"onSelectRow(row)\"\n          class=\"bmb_table-row\"\n          [class.bmb_table-expandible]=\"expandedElement === row\"\n          [ngClass]=\"{\n            'bmb_table-even': isEven(i),\n            'bmb_table-odd': isOdd(i)\n          }\"\n        ></tr>\n\n        <ng-container *ngIf=\"tableConfig?.isExpandible\">\n          <tr\n            mat-row\n            *matRowDef=\"let row; columns: ['expandedDetail']; let i = dataIndex\"\n            class=\"bmb_table-details\"\n            [class.bmb_table-expanded]=\"expandedElement === row\"\n          ></tr>\n        </ng-container>\n      </table>\n    </section>\n    <!-- Paginator -->\n    <ng-container *ngIf=\"tableConfig?.isPaginable\" sticky>\n      <mat-paginator\n        #paginator\n        [length]=\"totalItems()\"\n        [pageSize]=\"this.pageSize()\"\n        [hidePageSize]=\"true\"\n        (page)=\"onPageEvent($event)\"\n      >\n      </mat-paginator>\n\n      <div class=\"bmb_table-paginator\">\n        <span class=\"bmb_table-paginator-text\">{{ getPaginationText() }}</span>\n\n        <button\n          [disabled]=\"\n            serverSide() ? currentPage() === 0 : !paginator?.hasPreviousPage()\n          \"\n          [ngClass]=\"{\n            'bmb_table-paginator-btn-disabled': serverSide()\n              ? currentPage() === 0\n              : !paginator?.hasPreviousPage()\n          }\"\n          (click)=\"serverSide() ? goToFirstPage() : paginator.firstPage()\"\n          class=\"bmb_table-paginator-btn\"\n        >\n          <bmb-icon\n            icon=\"keyboard_double_arrow_left\"\n            class=\"bmb_table-paginator-icon\"\n          />\n        </button>\n        <button\n          [disabled]=\"\n            serverSide() ? currentPage() === 0 : !paginator?.hasPreviousPage()\n          \"\n          [ngClass]=\"{\n            'bmb_table-paginator-btn-disabled': serverSide()\n              ? currentPage() === 0\n              : !paginator?.hasPreviousPage()\n          }\"\n          (click)=\"serverSide() ? goToPreviousPage() : paginator.previousPage()\"\n          class=\"bmb_table-paginator-btn\"\n        >\n          <bmb-icon\n            icon=\"keyboard_arrow_left\"\n            class=\"bmb_table-paginator-icon\"\n          />\n        </button>\n        <button\n          [disabled]=\"\n            serverSide()\n              ? currentPage() >= lastPage()\n              : !paginator?.hasNextPage()\n          \"\n          [ngClass]=\"{\n            'bmb_table-paginator-btn-disabled': serverSide()\n              ? currentPage() >= lastPage()\n              : !paginator?.hasNextPage()\n          }\"\n          (click)=\"serverSide() ? goToNextPage() : paginator.nextPage()\"\n          class=\"bmb_table-paginator-btn\"\n        >\n          <bmb-icon\n            icon=\"keyboard_arrow_right\"\n            class=\"bmb_table-paginator-icon\"\n          />\n        </button>\n        <button\n          [disabled]=\"\n            serverSide()\n              ? currentPage() >= lastPage()\n              : !paginator?.hasNextPage()\n          \"\n          [ngClass]=\"{\n            'bmb_table-paginator-btn-disabled': serverSide()\n              ? currentPage() >= lastPage()\n              : !paginator?.hasNextPage()\n          }\"\n          (click)=\"serverSide() ? goToLastPage() : paginator.lastPage()\"\n          class=\"bmb_table-paginator-btn\"\n        >\n          <bmb-icon\n            icon=\"keyboard_double_arrow_right\"\n            class=\"bmb_table-paginator-icon\"\n          />\n        </button>\n      </div>\n    </ng-container>\n  </div>\n</div>\n";

